/**
 * 选中文字后浮出的小工具条：词典 / 荧光笔 / 划线 / 笔记 / AI 解释 / 存知识卡。
 *
 * 它不是页面的一部分 —— 没选中文字就不存在，所以阅读时没有任何常驻工具栏
 * 挡在正文旁边。整条只有一行：字认图标，名字（「荧光笔·红」）交给悬浮提示，
 * 落在按钮上才浮出来 —— 相邻按钮之间滑动时提示会自己溜过去。点开「笔记」时
 * 整条换成一张小卡片，写完再收回去。
 *
 * mousedown 在按钮上会被挡掉：浏览器一按下鼠标就会清掉选区，挡掉默认行为
 * 之后，点工具条不会让刚才选中的文字散掉（输入框除外）。
 */
import {
  BookA,
  BookmarkPlus,
  Highlighter,
  NotebookPen,
  Sparkles,
  Trash2,
  Underline,
  X,
} from "lucide-react";
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type MouseEvent as ReactMouseEvent,
} from "react";
import { createPortal } from "react-dom";
import { cn } from "../../lib/cn";
import { WarmTip, WarmTipGroup } from "../controls/WarmTip";
import {
  READER_HIGHLIGHT_COLORS,
  annotationStyle,
  type ReaderAnnotation,
  type ReaderHighlightColor,
} from "../../lib/readerAnnotations";
import "./reader-selection-toolbar.css";

/** 一个个色点上的悬浮提示：墨色小牌子，跟卡片上的深色按钮同一种墨。 */
const INK_TOOLTIP = {
  side: "top",
  surfaceColor: "#2e323c",
  inkColor: "#f6f7fa",
  radius: 9,
  gap: 10,
  delay: 140,
} as const;

export interface ReaderSelectionToolbarProps {
  text: string;
  /** 视口坐标：选区水平中点和工具条要贴在的那条边。 */
  x: number;
  y: number;
  placement: "above" | "below";
  /** 选中的文字上已经有了这条标注时进入编辑态。 */
  annotation: ReaderAnnotation | null;
  /**
   * 打开选区的词典卡片（音标、词性、释义都在那张卡上）。
   * 不传就没有「词典」这一格 —— 练习页点不着词典。
   */
  onDictionary?: () => void;
  onHighlight: (color: ReaderHighlightColor) => void;
  /**
   * 划一条彩色下划线。不传就只有荧光笔那一排 —— 练习页没有划线需求，
   * 知识书里两排都开。
   */
  onUnderline?: (color: ReaderHighlightColor) => void;
  onSaveNote: (note: string, options: { toDrawer: boolean }) => void;
  /** 不传就收起「解释」——这处没有 AI 面板。 */
  onExplain?: () => void;
  /** 不传就收起「存卡」。 */
  onSaveCard?: () => void;
  onRemove: () => void;
  onDismiss: () => void;
}

export function ReaderSelectionToolbar({
  text,
  x,
  y,
  placement,
  annotation,
  onDictionary,
  onHighlight,
  onUnderline,
  onSaveNote,
  onExplain,
  onSaveCard,
  onRemove,
  onDismiss,
}: ReaderSelectionToolbarProps) {
  const toolbarRef = useRef<HTMLDivElement>(null);
  const [composing, setComposing] = useState(false);
  const [noteDraft, setNoteDraft] = useState(annotation?.note ?? "");
  const [shift, setShift] = useState(0);

  useEffect(() => {
    setComposing(false);
    setNoteDraft(annotation?.note ?? "");
    setShift(0);
  }, [annotation, text]);

  // 工具条是贴着选区长出来的：选到第一行时它会顶出屏幕顶，写笔记展开成卡片之后
  // 更容易越界。量一下自己的高度，越界就往回推，推回视口里为止。
  useLayoutEffect(() => {
    const element = toolbarRef.current;
    if (!element) return;
    setShift((current) => {
      const box = element.getBoundingClientRect();
      if (box.height > window.innerHeight - 20) return current;
      const over = 10 - box.top;
      const under = box.bottom - (window.innerHeight - 10);
      const delta = over > 0 ? over : under > 0 ? -under : 0;
      return delta === 0 ? current : current + delta;
    });
  }, [placement, composing, x, y, text, annotation]);

  useEffect(() => {
    const onPointerDown = (event: PointerEvent) => {
      if (
        toolbarRef.current &&
        !toolbarRef.current.contains(event.target as Node)
      ) {
        onDismiss();
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onDismiss();
    };
    const onScroll = () => onDismiss();
    window.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("scroll", onScroll);
    return () => {
      window.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("scroll", onScroll);
    };
  }, [onDismiss]);

  const keepSelection = (event: ReactMouseEvent<HTMLDivElement>) => {
    const target = event.target as HTMLElement;
    if (target.closest("textarea, input")) return;
    event.preventDefault();
  };

  return createPortal(
    <div
      ref={toolbarRef}
      className={cn(
        "reader-toolbar",
        composing && "is-composing",
        placement === "above" ? "is-above" : "is-below",
      )}
      style={
        { left: x, top: y, "--reader-toolbar-shift": `${shift}px` } as CSSProperties
      }
      role="dialog"
      aria-label="选中文字的标注工具"
      onMouseDown={keepSelection}
    >
      {composing ? (
        <form
          className="reader-toolbar__note"
          onSubmit={(event) => {
            event.preventDefault();
            const note = noteDraft.trim();
            if (!note) return;
            onSaveNote(note, { toDrawer: false });
          }}
        >
          <header>
            <NotebookPen size={13} />
            <span>我的理解</span>
            <button
              type="button"
              aria-label="关闭笔记"
              onClick={() => setComposing(false)}
            >
              <X size={13} />
            </button>
          </header>
          <blockquote>{text}</blockquote>
          {/* eslint-disable-next-line jsx-a11y/no-autofocus */}
          <textarea
            autoFocus
            value={noteDraft}
            maxLength={400}
            placeholder="这一段和我想的不一样…"
            aria-label="笔记内容"
            onChange={(event) => setNoteDraft(event.target.value)}
          />
          <footer>
            <button type="submit" className="is-primary" disabled={!noteDraft.trim()}>
              只存在书页
            </button>
            <button
              type="button"
              disabled={!noteDraft.trim()}
              onClick={() => onSaveNote(noteDraft.trim(), { toDrawer: true })}
            >
              存入 Notes 抽屉
            </button>
          </footer>
        </form>
      ) : (
        <WarmTipGroup delay={220} warmWindow={260} travel={280}>
          {onDictionary ? (
            <WarmTip content="查词典" {...INK_TOOLTIP}>
              <button
                type="button"
                className="is-lead"
                aria-label="查词典"
                onClick={onDictionary}
              >
                <BookA size={15} />
                词典
              </button>
            </WarmTip>
          ) : null}
          <div className="reader-toolbar__colors" role="group" aria-label="荧光笔颜色">
            <Highlighter className="reader-toolbar__tool" size={15} aria-hidden="true" />
            {READER_HIGHLIGHT_COLORS.map((color) => (
              <WarmTip
                key={color.id}
                content={`荧光笔·${color.zh}`}
                {...INK_TOOLTIP}
              >
                <button
                  type="button"
                  className={cn(
                    "is-color",
                    `is-${color.id}`,
                    annotation !== null &&
                      annotationStyle(annotation) === "highlight" &&
                      annotation.color === color.id &&
                      "is-active",
                  )}
                  aria-label={`荧光笔：${color.label}`}
                  onClick={() => onHighlight(color.id)}
                >
                  <span aria-hidden="true" />
                </button>
              </WarmTip>
            ))}
          </div>
          {onUnderline ? (
            <div
              className="reader-toolbar__colors reader-toolbar__colors--line"
              role="group"
              aria-label="划线颜色"
            >
              <Underline className="reader-toolbar__tool" size={15} aria-hidden="true" />
              {READER_HIGHLIGHT_COLORS.map((color) => (
                <WarmTip
                  key={color.id}
                  content={`划线·${color.zh}`}
                  {...INK_TOOLTIP}
                >
                  <button
                    type="button"
                    className={cn(
                      "is-color",
                      "is-line",
                      `is-${color.id}`,
                      annotation !== null &&
                        annotationStyle(annotation) === "underline" &&
                        annotation.color === color.id &&
                        "is-active",
                    )}
                    aria-label={`划线：${color.label}`}
                    onClick={() => onUnderline(color.id)}
                  >
                    <span aria-hidden="true" />
                  </button>
                </WarmTip>
              ))}
            </div>
          ) : null}
          <div className="reader-toolbar__actions">
            <WarmTip
              content={
                annotation?.note
                  ? `我的笔记：${annotation.note.slice(0, 80)}`
                  : "写笔记"
              }
              {...INK_TOOLTIP}
            >
              <button
                type="button"
                aria-label="写笔记"
                onClick={() => setComposing(true)}
              >
                <NotebookPen size={14} />
              </button>
            </WarmTip>
            {onExplain ? (
              <WarmTip content="AI 解释" {...INK_TOOLTIP}>
                <button type="button" aria-label="AI 解释" onClick={onExplain}>
                  <Sparkles size={14} />
                </button>
              </WarmTip>
            ) : null}
            {onSaveCard ? (
              <WarmTip content="存知识卡" {...INK_TOOLTIP}>
                <button type="button" aria-label="存知识卡" onClick={onSaveCard}>
                  <BookmarkPlus size={14} />
                </button>
              </WarmTip>
            ) : null}
            {annotation ? (
              <WarmTip content="取消这条标注" {...INK_TOOLTIP}>
                <button
                  type="button"
                  className="is-danger"
                  aria-label="取消这条标注"
                  onClick={onRemove}
                >
                  <Trash2 size={14} />
                </button>
              </WarmTip>
            ) : null}
          </div>
        </WarmTipGroup>
      )}
    </div>,
    document.body,
  );
}
