import {
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./card-fan.css";

export interface FanCard {
  id: string;
  title: string;
  /** 卡面正文，两三行。 */
  body?: string;
  /** 卡脚的小字：出处、日期之类。 */
  meta?: string;
}

export interface CardFanProps {
  items: FanCard[];
  /** 受控的当前卡；不传就自己记。 */
  activeIndex?: number;
  onActiveChange?: (index: number) => void;
  /** 点正中间那张时打开它。 */
  onSelect?: (item: FanCard) => void;
  className?: string;
  emptyLabel?: string;
  ariaLabel?: string;
  hint?: string;
}

/** 每一档往右挪多远、往下沉多少、歪多少度、缩多少。 */
const STEP_X = 104;
const STEP_Y = 13;
const STEP_TILT = 3.4;
const STEP_SCALE = 0.078;
const STEP_FADE = 0.32;
/** 这个距离以外就不画了（省得一堆卡片叠在同一个位置上）。 */
const SPAN = 2.2;

/** 拖过这么多才算要换一张。 */
const DRAG_STEP = 52;
/** 拖动时手上的位移最多压到这么多，超了就打回去（有点阻尼的意思）。 */
const DRAG_LIMIT = STEP_X * 1.15;
/** 滚轮攒够这么多换一张。 */
const WHEEL_STEP = 110;

const clamp = (value: number, low: number, high: number) =>
  Math.max(low, Math.min(high, value));

/**
 * 一叠摊开的卡片：正中间那张摆正、看得清，左右两张像被人捏在手里似的
 * 往两边斜出去，再往外就退没了。
 *
 * 换卡有三条路 —— 拖着走（手跟着动，松手按拖了多远决定翻不翻）、滚轮、
 * 左右方向键；点边上的卡把它请到中间，点中间那张才是打开它。
 *
 * 拖动时靠一个 CSS 变量（--fan-shift）把整摊一起挪，手指停在哪卡就停在哪；
 * 松手把变量归零、该翻的翻一格 —— 归零和翻页都是 CSS 过渡，不用逐帧算。
 */
export function CardFan({
  items,
  activeIndex,
  onActiveChange,
  onSelect,
  className,
  emptyLabel = "还没有卡片。",
  ariaLabel = "卡片",
  hint = "",
}: CardFanProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const [innerIndex, setInnerIndex] = useState(0);
  /** 手上那点位移（px）。只有拖动的时候非零。 */
  const [shift, setShift] = useState(0);
  /** 同一个数还留一份在手边：松手那一下要照最新的位移决定翻不翻，
      而事件回调里读到的 state 可能还是上一次渲染的。 */
  const shiftRef = useRef(0);
  const cardRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const dragRef = useRef<{ pointerId: number; startX: number; captured: boolean } | null>(null);
  /** 拖动过之后跟着 pointerup 来的那一下 click 要吞掉。 */
  const draggedRef = useRef(false);
  const wheelAccum = useRef(0);

  const total = items.length;
  const index = total ? clamp(activeIndex ?? innerIndex, 0, total - 1) : 0;

  const applyShift = useCallback((value: number) => {
    shiftRef.current = value;
    setShift(value);
  }, []);

  const commitIndex = useCallback(
    (next: number) => {
      const clamped = clamp(next, 0, Math.max(0, total - 1));
      if (activeIndex === undefined) setInnerIndex(clamped);
      onActiveChange?.(clamped);
    },
    [activeIndex, onActiveChange, total],
  );

  const handleWheel = useCallback(
    (event: WheelEvent) => {
      if (total < 2) return;
      const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
      if (Math.abs(delta) < 3) return;
      wheelAccum.current += delta;
      if (Math.abs(wheelAccum.current) < WHEEL_STEP) return;
      const step = wheelAccum.current > 0 ? 1 : -1;
      wheelAccum.current = 0;
      // 到头了就交还给页面，别把整页的滚动锁死。
      if (index + step < 0 || index + step > total - 1) return;
      event.preventDefault();
      commitIndex(index + step);
    },
    [commitIndex, index, total],
  );

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.addEventListener("wheel", handleWheel, { passive: false });
    return () => root.removeEventListener("wheel", handleWheel);
  }, [handleWheel]);

  const handlePointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      if (event.button !== 0 || total < 2) return;
      draggedRef.current = false;
      dragRef.current = { pointerId: event.pointerId, startX: event.clientX, captured: false };
    },
    [total],
  );

  const handlePointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    const dx = event.clientX - drag.startX;
    // 真挪起来了才把指针接过来：一按下就 capture，松手那下 click 会被
    // 重定到容器上，卡片自己收不到 —— 点中间那张就开不了。
    if (!drag.captured) {
      if (Math.abs(dx) < 6) return;
      drag.captured = true;
      draggedRef.current = true;
      event.currentTarget.setPointerCapture?.(event.pointerId);
    }
    // 到头了还往回拖就没那么好拖（位移减半），手感上知道到头了。
    const eased = dx * 0.62;
    const atEdge =
      (index === 0 && eased > 0) || (index === total - 1 && eased < 0);
    applyShift(clamp(atEdge ? eased * 0.5 : eased, -DRAG_LIMIT, DRAG_LIMIT));
  }, [applyShift, index, total]);

  const endDrag = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      dragRef.current = null;
      if (!drag || drag.pointerId !== event.pointerId) return;
      if (event.currentTarget.hasPointerCapture?.(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
      // 先归零再翻页，而且不写在 setState 的更新函数里 —— 那个函数
      // React 有可能在渲染别的东西的时候顺手跑一遍，从里面去动父组件的
      // state 就是「render 期间更新另一个组件」，会报错。
      const travelled = shiftRef.current;
      applyShift(0);
      if (Math.abs(travelled) > DRAG_STEP) {
        // 往左拖（位移是负的）就是往后翻。
        commitIndex(index + (travelled < 0 ? 1 : -1));
      }
    },
    [applyShift, commitIndex, index],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      const step =
        event.key === "ArrowRight" || event.key === "ArrowDown"
          ? 1
          : event.key === "ArrowLeft" || event.key === "ArrowUp"
            ? -1
            : 0;
      if (!step) {
        if (event.key === "Enter" || event.key === " ") {
          const card = items[index];
          if (!card) return;
          event.preventDefault();
          onSelect?.(card);
        }
        return;
      }
      event.preventDefault();
      const next = clamp(index + step, 0, total - 1);
      if (next === index) return;
      commitIndex(next);
      // 焦点得跟着挪：旧的这张马上要变成不可 Tab 的，焦点留在那儿会跳出去。
      cardRefs.current[next]?.focus({ preventScroll: true });
    },
    [commitIndex, index, items, onSelect, total],
  );

  if (!total) {
    return (
      <div className={["card-fan", "card-fan--empty", className].filter(Boolean).join(" ")}>
        <p className="card-fan__empty">{emptyLabel}</p>
      </div>
    );
  }

  return (
    <div
      ref={rootRef}
      className={["card-fan", prefersReducedMotion && "is-static", className]
        .filter(Boolean)
        .join(" ")}
      role="group"
      aria-label={ariaLabel}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={endDrag}
      onPointerCancel={endDrag}
      onKeyDown={handleKeyDown}
    >
      <div
        className="card-fan__stage"
        style={{ "--fan-shift": `${shift.toFixed(1)}px` } as CSSProperties}
      >
        {items.map((item, itemIndex) => {
          const offset = itemIndex - index;
          const distance = Math.abs(offset);
          if (distance > SPAN) return null;
          const isFront = distance === 0;
          return (
            <button
              type="button"
              key={item.id}
              ref={(node) => {
                cardRefs.current[itemIndex] = node;
              }}
              className={["card-fan__card", isFront && "is-front"]
                .filter(Boolean)
                .join(" ")}
              data-offset={offset}
              aria-current={isFront ? "true" : undefined}
              // 只有正中间那张在 Tab 顺序里；其余的还看得见、能点，但不占 Tab。
              tabIndex={isFront ? 0 : -1}
              style={
                {
                  "--fan-x": `${offset * STEP_X}px`,
                  "--fan-y": `${offset * STEP_Y}px`,
                  "--fan-tilt": `${offset * STEP_TILT}deg`,
                  "--fan-scale": `${(1 - distance * STEP_SCALE).toFixed(3)}`,
                  opacity: Math.max(0, 1 - distance * STEP_FADE),
                  zIndex: 40 - Math.round(distance * 10),
                } as CSSProperties
              }
              onClick={() => {
                if (draggedRef.current) {
                  draggedRef.current = false;
                  return;
                }
                if (!isFront) {
                  commitIndex(itemIndex);
                  return;
                }
                onSelect?.(item);
              }}
            >
              <strong className="card-fan__title">{item.title}</strong>
              {item.body ? <p className="card-fan__body">{item.body}</p> : null}
              {item.meta ? <small className="card-fan__meta">{item.meta}</small> : null}
            </button>
          );
        })}
      </div>

      <div className="card-fan__dots" aria-hidden="true">
        {items.map((item, itemIndex) => (
          <i key={item.id} data-on={itemIndex === index ? "" : undefined} />
        ))}
      </div>

      {hint ? <p className="card-fan__hint">{hint}</p> : null}
    </div>
  );
}

export default CardFan;
